using System.ComponentModel;
using System.Net;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClientOptions
    {
        // Use environment variable for base URL override if needed
    }, apiKey: apiKey));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define tools
var searchTool = AIFunctionFactory.Create(WebSearchTool.SearchAsync);
var addNoteTool = AIFunctionFactory.Create(NoteTool.AddNote);
var getNotesTool = AIFunctionFactory.Create(NoteTool.GetNotes);

// Create the agent
var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the web_search tool.
        2. Taking notes on key findings using the add_note tool.
        3. Searching for multiple aspects of the topic to get comprehensive coverage.
        4. Once you have gathered enough information, retrieve all notes and produce a 
           well-structured summary of your findings.

        Always take notes as you research so you can produce a comprehensive final summary.
        """,
    Tools = [searchTool, addNoteTool, getNotesTool],
    DefaultChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
});

// Run the research agent
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Tool Definitions ---

/// <summary>Simulates web search results for demonstration purposes.</summary>
static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query to look up")] string query)
    {
        // In production, replace with a real search API (Bing, Google, etc.)
        await Task.Delay(100); // Simulate network latency

        return $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview article covering key aspects of {query}. 
               This topic encompasses multiple dimensions including historical context, 
               current developments, and future implications.

            2. [Research Paper] A comprehensive study on {query} published in 2024, 
               highlighting recent breakthroughs and methodological advances.

            3. [News Article] Recent developments in {query} - experts weigh in on 
               the latest trends and their potential impact on the field.

            Note: This is a simulated search. Replace WebSearchTool.SearchAsync with 
            a real search API integration (e.g., Bing Search API) for production use.
            """;
    }
}

/// <summary>Provides note-taking capabilities for the research agent.</summary>
static class NoteTool
{
    private static readonly List<string> _notes = [];

    [Description("Adds a research note capturing a key finding or insight.")]
    public static string AddNote(
        [Description("The note content to save")] string content)
    {
        _notes.Add(content);
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all research notes taken so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }
}

