using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey: apiKey));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define tools
var searchTool = AIFunctionFactory.Create(WebSearchTool.SearchAsync);
var addNoteTool = AIFunctionFactory.Create(NoteTool.AddNote);
var getNotesTool = AIFunctionFactory.Create(NoteTool.GetNotes);

// Create the inner agent with tool-calling capabilities
var chatAgent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
}, tools: [searchTool, addNoteTool, getNotesTool]);

// Wrap in a LoopAgent to allow multi-step tool calling with iteration limits
var loopAgent = new LoopAgent(
    chatAgent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 10 });

// Run the research agent
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var prompt = new ChatMessage(ChatRole.User, $"""
    Research the following topic and provide a comprehensive summary: {topic}

    Instructions:
    1. Use the web_search tool to search for information about different aspects of this topic.
    2. Use the add_note tool to record key findings as you go.
    3. Perform at least 2-3 searches to cover different angles.
    4. After gathering enough information, use get_notes to review your findings.
    5. Produce a well-structured final summary of your research.
    """);

var session = new ChatClientAgentSession();

var response = await loopAgent.RunAsync(prompt, session, cancellationToken: CancellationToken.None);

// Print the final response
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n=== Research Complete ===");

// --- Tool Definitions ---

