static class NoteTool
{
    private static readonly List<string> _notes = [];

    [Description("Adds a research note capturing a key finding or insight.")]
    public static string AddNote(
        [Description("The note content to save")] string content)
    {
        _notes.Add(content);
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all research notes taken so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
